import { AttrHost } from '../constants';
// import { enqueueRender } from '../component';

/**
 * Find the closest error boundary to a thrown error and call it
 * @param {object} error The thrown value
 * @param {import('../internal').VNode} vnode The vnode that threw
 * the error that was caught (except for unmounting when this parameter
 * is the highest parent that was being unmounted)
 */
export function _catchError(error, vnode) {
	/** @type {import('../internal').Component} */
	let component, ctor, handled;

	const wasHydrating = vnode._hydrating;

	for (; (vnode = vnode._parent); ) {
		if ((component = vnode._component) && !component._processingException) {
			try {
				ctor = component.constructor;

				if (ctor && ctor.getDerivedStateFromError != null) {
					component.setState(ctor.getDerivedStateFromError(error));
					handled = component._dirty;
				}

				if (component.componentDidCatch != null) {
					component.componentDidCatch(error);
					handled = component._dirty;
				}

				// This is an error boundary. Mark it as having bailed out, and whether it was mid-hydration.
				if (handled) {
					vnode._hydrating = wasHydrating;
					return (component._pendingError = component);
				}
			} catch (e) {
				error = e;
			}
		}
	}

	throw error;
}

/**
 * Markup payload for dangerouslySetInnerHTML reconciliation.
 * @param {object | null | undefined} newHtml
 * @param {object | null | undefined} oldHtml
 */
export function MarkupHost(newHtml, oldHtml) {
	this.__html = newHtml && newHtml.__html;
	this.previous = oldHtml;
}

MarkupHost.prototype.oldContent = function() {
	return this.previous && this.previous.__html;
};

/**
 * DOM field snapshot used while applying host node properties.
 * @param {import('../internal').PreactElement} dom
 */
export function DomHost(dom) {
	this.value = dom.value;
	this.checked = dom.checked;
	this.innerHTML = dom.innerHTML;
	this._node = dom;
}

DomHost.prototype.attributeAt = function(index) {
	const attrs = this._node && this._node.attributes;
	if (!attrs || index >= attrs.length) {
		return new AttrHost(null);
	}
	return new AttrHost(attrs[index]);
};

DomHost.prototype.writeInnerHTML = function(html) {
	this._node.innerHTML = html;
};

