import { createVNodeHost } from './create-element';

/**
 * Assign properties from `props` to `obj`
 * @template O, P The obj and props types
 * @param {O} obj The object to copy properties to
 * @param {P} props The object to copy properties from
 * @returns {O & P}
 */
export function assign(obj, props) {
	for (let i in props) obj[i] = props[i];
	return /** @type {O & P} */ (obj);
}

/**
 * Remove a child node from its parent if attached. This is a workaround for
 * IE11 which doesn't support `Element.prototype.remove()`. Using this function
 * is smaller than including a dedicated polyfill.
 * @param {Node} node The node to remove
 */
export function removeNode(node) {
	let parentNode = node.parentNode;
	if (parentNode) parentNode.removeChild(node);
}

/**
 * Applies host node properties after the main prop diff.
 */
export function HostUpdater() {
	this.hydrating = false;
}

/**
 * Reconcile innerHTML, value, and checked against the live host node.
 * @param {import('./internal').VNode} vnode
 * @param {object} newProps
 * @param {object} oldProps
 * @param {import('./internal').PreactElement} dom
 * @param {Array<import('./internal').PreactElement> | null} excessDomChildren
 */
HostUpdater.prototype.applyHostProperties = function(
	vnode,
	newProps,
	oldProps,
	dom,
	isHydrating,
	excessDomChildren
) {
	this.hydrating = isHydrating;
	const parts = createVNodeHost(vnode, newProps, oldProps, dom);
	const vnodeHost = parts.vnodeHost;
	const propHost = parts.propHost;
	const markupHost = parts.markupHost;
	const domHost = parts.domHost;
	let nextOldProps = oldProps;
	let valueToSet;
	let checkedToSet;

	if (!this.hydrating) {
		if (excessDomChildren != null) {
			nextOldProps = {};
			let current = domHost.attributeAt(0);
			for (let i = 0; current && current.name != null; i++) {
				nextOldProps[current.name] = current.value;
				current = domHost.attributeAt(i + 1);
			}
		}

		const newHtml = propHost.dangerouslySetInnerHTML;
		const oldHtml = markupHost.previous;
		if (newHtml || oldHtml) {
			if (
				!newHtml ||
				((!oldHtml || markupHost.__html != markupHost.oldContent()) &&
					markupHost.__html !== domHost.innerHTML)
			) {
				domHost.writeInnerHTML(markupHost.__html || '');
			}
		}
	}

	if (propHost.dangerouslySetInnerHTML) {
		vnodeHost._children = [];
	}

	if (!this.hydrating) {
		let i = propHost.value;
		if (i !== undefined && i !== domHost.value) {
			valueToSet = i;
		}
		i = propHost.checked;
		if (i !== undefined && i !== domHost.checked) {
			checkedToSet = i;
		}
	}

	return {
		oldProps: nextOldProps,
		skipChildren: !!propHost.dangerouslySetInnerHTML,
		hostChildren: vnodeHost._children,
		childContent: propHost.children,
		valueToSet,
		checkedToSet,
		type: vnodeHost.type
	};
};

export const hostUpdater = new HostUpdater();

